pub fn is_palindrome(text: Vec<char>) -> (bool) {
    fn lower_ascii(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            // Safe because it's guaranteed to be ASCII uppercase.
            ((c as u8) + (b'a' - b'A')) as char
        } else {
            c
        }
    }

    let n = text.len();
    for i in 0..(n / 2) {
        if lower_ascii(text[i]) != lower_ascii(text[n - 1 - i]) {
            return (false);
        }
    }
    (true)
}